-- 中文 A1 課程（Mandarin A1 Course (Kolecion)）：對應 TOCFL Level 1（CEFR A1），共 20 個單元、240 小時，專為在台菲律賓移工學生設計。
-- 12 個 TOCFL 基礎主題單元加 7 個移工職場與生活單元，最後是總複習；每個單元都有詞彙、例句與對話（中文 | 拼音 | 英文），不重複詞彙目標 800 個。
-- 會建立「中文A1」證照與「Mandarin A1 Course (Kolecion)」課程；不會動到既有的 CAV、中文N1 課程與單元。
-- 可重複執行：已存在的證照、課程、單元（名稱相同）不會被覆蓋，你在網站上編輯過的內容不會被蓋掉。
--
-- 用法（在專案資料夾，center_email 換成訓練中心會員的 Email）：
--   docker compose cp scripts/seed-mandarin-a1-course.sql postgres:/tmp/seed-a1.sql
--   docker compose exec -T -e PGCLIENTENCODING=UTF8 postgres psql -U postgres -d saas_demo -v center_email=center@example.com -f /tmp/seed-a1.sql
-- （不要用 Get-Content 管線：Windows PowerShell 會把中文編碼弄壞，造成 unterminated quoted string。）
--
-- 課程費用不會由這支腳本設定（預設為空白，網站顯示「—」），請到訓練中心的課程頁填入費用與幣別。
\set ON_ERROR_STOP on

-- 找不到訓練中心就中止，不寫入任何資料。
SELECT COALESCE(max(id), 0) AS center_id FROM hr_members
WHERE role = 'training_center' AND lower(email) = lower(:'center_email') \gset
SELECT :center_id = 0 AS missing_center \gset
\if :missing_center
  \echo '找不到這個 Email 的訓練中心會員（會員類型必須是訓練中心），已中止。'
  \quit
\endif

BEGIN;

-- 這些欄位網站更新後也會自動建立，這裡先補上以免順序問題（與 seed-training-courses.sql 相同）。
ALTER TABLE hr_tc_courses ADD COLUMN IF NOT EXISTS fee NUMERIC(12,2);
ALTER TABLE hr_tc_courses ADD COLUMN IF NOT EXISTS currency TEXT NOT NULL DEFAULT 'PHP';
ALTER TABLE hr_tc_course_units ADD COLUMN IF NOT EXISTS vocabulary TEXT NOT NULL DEFAULT '';
ALTER TABLE hr_tc_course_units ADD COLUMN IF NOT EXISTS dialogue TEXT NOT NULL DEFAULT '';
ALTER TABLE hr_tc_course_units ADD COLUMN IF NOT EXISTS category TEXT NOT NULL DEFAULT '';
ALTER TABLE hr_tc_course_units ADD COLUMN IF NOT EXISTS category_en TEXT NOT NULL DEFAULT '';

INSERT INTO hr_tc_certifications(center_id, name)
VALUES (:center_id, '中文A1')
ON CONFLICT (center_id, name) DO NOTHING;

INSERT INTO hr_tc_courses(center_id, certification_id, name)
SELECT :center_id, c.id, 'Mandarin A1 Course (Kolecion)'
FROM hr_tc_certifications c WHERE c.center_id = :center_id AND c.name = '中文A1'
ON CONFLICT (center_id, certification_id, name) DO NOTHING;

-- 課程時數 240 小時（原本沒填才補）。
UPDATE hr_tc_courses SET hours = 240, updated_at = NOW()
WHERE center_id = :center_id AND name = 'Mandarin A1 Course (Kolecion)' AND hours IS NULL;

SELECT COALESCE(max(co.id), 0) AS course_id FROM hr_tc_courses co
JOIN hr_tc_certifications c ON c.id = co.certification_id
WHERE co.center_id = :center_id AND c.name = '中文A1' AND co.name = 'Mandarin A1 Course (Kolecion)' \gset

-- 新增單元（名稱相同的不會覆蓋）。
WITH inserted AS (
  INSERT INTO hr_tc_course_units(center_id, course_id, position, name, name_en, hours, topics, topics_en, examples, vocabulary, dialogue, category, category_en)
  SELECT :center_id, :course_id, v.position, v.name, v.name_en, v.hours, v.topics, v.topics_en, v.examples, v.vocabulary, v.dialogue, v.category, v.category_en
  FROM (VALUES
    (1, E'發音與聲調', E'Pronunciation & Tones', 8, E'注音與拼音、四個聲調與輕聲、三聲連讀與「不」「一」的變調、課堂用語', E'Zhuyin and pinyin, the four tones and the neutral tone, third-tone sandhi and the tone changes of 不 and 一, classroom phrases', E'你好。 | Nǐ hǎo. | Hello.\n謝謝。 | Xièxie. | Thank you.\n請再說一次。 | Qǐng zài shuō yí cì. | Please say it again.\n我不懂。 | Wǒ bù dǒng. | I do not understand.', E'媽 | mā | mother\n麻 | má | hemp\n馬 | mǎ | horse\n罵 | mà | to scold\n你 | nǐ | you\n好 | hǎo | good\n我 | wǒ | I\n他 | tā | he\n她 | tā | she\n是 | shì | to be\n不 | bù | not\n謝謝 | xièxie | thank you\n再見 | zàijiàn | goodbye\n對不起 | duìbuqǐ | sorry\n老師 | lǎoshī | teacher\n同學 | tóngxué | classmate\n請問 | qǐngwèn | excuse me', E'A：你好！ | Nǐ hǎo! | Hello!\nB：你好！ | Nǐ hǎo! | Hello!\nA：請問，你叫什麼名字？ | Qǐngwèn, nǐ jiào shénme míngzi? | Excuse me, what is your name?\nB：我叫王明。 | Wǒ jiào Wáng Míng. | My name is Wang Ming.\nA：請再說一次。 | Qǐng zài shuō yí cì. | Please say it again.\nB：王，明。 | Wáng, Míng. | Wang, Ming.\nA：謝謝。 | Xièxie. | Thank you.\nB：不客氣。 | Bú kèqi. | You are welcome.', E'基礎', E'Basics'),
    (2, E'問候與自我介紹', E'Greetings & Introductions', 10, E'打招呼、姓名、國籍、職業、「是／不是」句、「嗎」與「呢」問句', E'Greetings, names, nationality and jobs, 是 / 不是 sentences, questions with 嗎 and 呢', E'我叫王明。 | Wǒ jiào Wáng Míng. | My name is Wang Ming.\n我是學生。 | Wǒ shì xuéshēng. | I am a student.\n你是台灣人嗎？ | Nǐ shì Táiwān rén ma? | Are you Taiwanese?', E'我們 | wǒmen | we\n你們 | nǐmen | you (plural)\n他們 | tāmen | they\n這 | zhè | this\n那 | nà | that\n誰 | shéi | who\n你好 | nǐ hǎo | hello\n早安 | zǎo ān | good morning\n晚安 | wǎn ān | good night\n不客氣 | bú kèqi | you are welcome\n沒關係 | méi guānxi | it is okay\n請 | qǐng | please\n叫 | jiào | to be called\n名字 | míngzi | name\n姓 | xìng | surname\n什麼 | shénme | what\n人 | rén | person\n學生 | xuéshēng | student\n朋友 | péngyǒu | friend\n醫生 | yīshēng | doctor\n工作 | gōngzuò | job\n台灣 | Táiwān | Taiwan\n中國 | Zhōngguó | China\n美國 | Měiguó | the United States\n日本 | Rìběn | Japan\n英國 | Yīngguó | the United Kingdom\n國家 | guójiā | country\n嗎 | ma | question particle\n呢 | ne | and you? (particle)\n也 | yě | also\n都 | dōu | all\n很 | hěn | very\n認識 | rènshi | to know (someone)\n高興 | gāoxìng | glad\n對 | duì | correct', E'A：你好，我叫王明。請問你叫什麼名字？ | Nǐ hǎo, wǒ jiào Wáng Míng. Qǐngwèn nǐ jiào shénme míngzi? | Hello, I am Wang Ming. What is your name?\nB：我叫安娜。你是台灣人嗎？ | Wǒ jiào Ānnà. Nǐ shì Táiwān rén ma? | I am Anna. Are you Taiwanese?\nA：對，我是台灣人。你呢？ | Duì, wǒ shì Táiwān rén. Nǐ ne? | Yes, I am Taiwanese. And you?\nB：我是美國人，我是學生。 | Wǒ shì Měiguó rén, wǒ shì xuéshēng. | I am American. I am a student.\nA：我是老師。很高興認識你。 | Wǒ shì lǎoshī. Hěn gāoxìng rènshi nǐ. | I am a teacher. Nice to meet you.\nB：我也很高興認識你。 | Wǒ yě hěn gāoxìng rènshi nǐ. | I am glad to meet you too.', E'基礎', E'Basics'),
    (3, E'數字、日期與時間', E'Numbers, Dates & Time', 11, E'數字與電話號碼、年月日與星期、幾點幾分、「幾」與「多少」、「兩」與「二」、約定見面時間', E'Numbers and phone numbers, years, months, dates and weekdays, telling time, 幾 versus 多少, 兩 versus 二, arranging a meeting time', E'今天星期五。 | Jīntiān xīngqīwǔ. | Today is Friday.\n現在兩點半。 | Xiànzài liǎng diǎn bàn. | It is half past two.\n你的電話號碼是多少？ | Nǐ de diànhuà hàomǎ shì duōshao? | What is your phone number?', E'零 | líng | zero\n一 | yī | one\n二 | èr | two\n兩 | liǎng | two (before a measure word)\n三 | sān | three\n四 | sì | four\n五 | wǔ | five\n六 | liù | six\n七 | qī | seven\n八 | bā | eight\n九 | jiǔ | nine\n十 | shí | ten\n百 | bǎi | hundred\n千 | qiān | thousand\n幾 | jǐ | how many (small number)\n多少 | duōshao | how many or how much\n什麼時候 | shénme shíhou | when\n年 | nián | year\n月 | yuè | month\n號 | hào | day of the month\n星期 | xīngqī | week\n星期天 | xīngqītiān | Sunday\n週末 | zhōumò | weekend\n今天 | jīntiān | today\n明天 | míngtiān | tomorrow\n昨天 | zuótiān | yesterday\n現在 | xiànzài | now\n上午 | shàngwǔ | morning (before noon)\n下午 | xiàwǔ | afternoon\n晚上 | wǎnshang | evening\n早上 | zǎoshang | early morning\n點 | diǎn | o''clock\n分 | fēn | minute\n半 | bàn | half\n電話 | diànhuà | telephone\n號碼 | hàomǎ | number (code)\n生日 | shēngrì | birthday\n歲 | suì | years old\n今年 | jīnnián | this year\n個 | gè | general measure word', E'A：你明天有空嗎？ | Nǐ míngtiān yǒu kòng ma? | Are you free tomorrow?\nB：有，明天星期五，下午兩點可以嗎？ | Yǒu, míngtiān xīngqīwǔ, xiàwǔ liǎng diǎn kěyǐ ma? | Yes. Tomorrow is Friday. Is 2 p.m. okay?\nA：可以。你的電話號碼是多少？ | Kěyǐ. Nǐ de diànhuà hàomǎ shì duōshao? | Sure. What is your phone number?\nB：零九一二，三四五六，七八九。 | Líng jiǔ yāo èr, sān sì wǔ liù, qī bā jiǔ. | 0912-345-678 (read digit by digit)\nA：你的生日是幾月幾號？ | Nǐ de shēngrì shì jǐ yuè jǐ hào? | What is the date of your birthday?\nB：我的生日是十一月二十號。 | Wǒ de shēngrì shì shíyī yuè èrshí hào. | My birthday is on November 20.', E'基礎', E'Basics'),
    (4, E'家人與朋友', E'Family & Friends', 10, E'家人稱呼與人數、年齡與職業、「有／沒有」句、「的」、「和／也／都」、量詞、描述朋友', E'Family terms and how many people, age and jobs, 有 / 沒有 sentences, 的, 和 / 也 / 都, measure words, describing a friend', E'我家有五個人。 | Wǒ jiā yǒu wǔ gè rén. | There are five people in my family.\n我沒有弟弟。 | Wǒ méiyǒu dìdi. | I do not have a younger brother.\n他是我的朋友。 | Tā shì wǒ de péngyǒu. | He is my friend.', E'家 | jiā | home\n爸爸 | bàba | father\n媽媽 | māma | mother\n哥哥 | gēge | older brother\n姐姐 | jiějie | older sister\n弟弟 | dìdi | younger brother\n妹妹 | mèimei | younger sister\n爺爺 | yéye | grandfather\n奶奶 | nǎinai | grandmother\n孩子 | háizi | child\n先生 | xiānsheng | Mr. or husband\n太太 | tàitai | Mrs. or wife\n男生 | nánshēng | boy\n女生 | nǚshēng | girl\n小孩 | xiǎohái | little kid\n同事 | tóngshì | coworker\n鄰居 | línjū | neighbor\n工程師 | gōngchéngshī | engineer\n護士 | hùshi | nurse\n公司 | gōngsī | company\n有 | yǒu | to have\n沒有 | méiyǒu | to not have\n住 | zhù | to live\n在 | zài | to be at\n喜歡 | xǐhuan | to like\n高 | gāo | tall\n矮 | ǎi | short\n年輕 | niánqīng | young\n大 | dà | big\n小 | xiǎo | small\n忙 | máng | busy\n可愛 | kě ài | cute\n位 | wèi | polite measure word for people\n的 | de | possessive particle\n和 | hé | and\n多大 | duō dà | how old', E'A：你家有幾個人？ | Nǐ jiā yǒu jǐ gè rén? | How many people are in your family?\nB：我家有五個人，爸爸、媽媽、哥哥、妹妹和我。 | Wǒ jiā yǒu wǔ gè rén, bàba, māma, gēge, mèimei hé wǒ. | Five: Dad, Mom, my older brother, my younger sister and me.\nA：你哥哥做什麼工作？ | Nǐ gēge zuò shénme gōngzuò? | What does your older brother do?\nB：他是醫生，今年二十八歲。 | Tā shì yīshēng, jīnnián èrshíbā suì. | He is a doctor and is 28 this year.\nA：你媽媽也工作嗎？ | Nǐ māma yě gōngzuò ma? | Does your mother work too?\nB：她在公司工作，爸爸和媽媽都很忙。 | Tā zài gōngsī gōngzuò, bàba hé māma dōu hěn máng. | She works at a company. Dad and Mom are both busy.', E'人與家庭', E'People & Family'),
    (5, E'飲食與點餐', E'Food & Ordering', 11, E'主食、肉類、蔬果與飲料、餐廳點餐與忌口、內用與外帶、買單', E'Staples, meat, fruit, vegetables and drinks, ordering and dietary requests, eating in or taking out, paying the bill', E'我要一碗麵。 | Wǒ yào yì wǎn miàn. | I want a bowl of noodles.\n請給我菜單。 | Qǐng gěi wǒ càidān. | Please give me the menu.\n這個很好吃。 | Zhège hěn hǎochī. | This is very delicious.', E'飯 | fàn | rice\n麵 | miàn | noodles\n麵包 | miànbāo | bread\n水餃 | shuǐjiǎo | dumplings\n包子 | bāozi | steamed bun\n蛋 | dàn | egg\n牛肉麵 | niúròumiàn | beef noodle soup\n肉 | ròu | meat\n雞肉 | jīròu | chicken\n豬肉 | zhūròu | pork\n魚 | yú | fish\n蔬菜 | shūcài | vegetables\n水果 | shuǐguǒ | fruit\n蘋果 | píngguǒ | apple\n香蕉 | xiāngjiāo | banana\n水 | shuǐ | water\n茶 | chá | tea\n咖啡 | kāfēi | coffee\n牛奶 | niúnǎi | milk\n果汁 | guǒzhī | juice\n喝 | hē | to drink\n吃 | chī | to eat\n餐廳 | cāntīng | restaurant\n菜單 | càidān | menu\n服務員 | fúwùyuán | waiter\n買單 | mǎidān | to pay the bill\n內用 | nèiyòng | eat in\n外帶 | wàidài | takeout\n筷子 | kuàizi | chopsticks\n要 | yào | to want\n點菜 | diǎn cài | to order food\n給 | gěi | to give\n好吃 | hǎochī | delicious\n辣 | là | spicy\n鹹 | xián | salty\n燙 | tàng | burning hot\n好喝 | hǎohē | tasty (drink)\n便宜 | piányi | cheap\n一點 | yìdiǎn | a little\n不要 | búyào | do not want', E'A：你們幾位？要內用還是外帶？ | Nǐmen jǐ wèi? Yào nèiyòng háishi wàidài? | How many of you? Eat in or takeout?\nB：兩位，內用。請給我們菜單。 | Liǎng wèi, nèiyòng. Qǐng gěi wǒmen càidān. | Two people, eating in. The menu, please.\nA：好的。請問要點什麼？ | Hǎo de. Qǐngwèn yào diǎn shénme? | OK. What would you like to order?\nB：我要一碗牛肉麵，不要辣。 | Wǒ yào yì wǎn niúròumiàn, búyào là. | I want a bowl of beef noodle soup, not spicy.\nA：要喝茶嗎？ | Yào hē chá ma? | Would you like some tea?\nB：我要一杯茶。請問多少錢？ | Wǒ yào yì bēi chá. Qǐngwèn duōshao qián? | I want a cup of tea. How much is it?\nA：一共一百二十元。 | Yígòng yìbǎi èrshí yuán. | 120 dollars in total.', E'購物與飲食', E'Shopping & Food'),
    (6, E'購物與價錢', E'Shopping & Money', 12, E'問價與議價、商店與商品、顏色與尺寸、試穿、付錢與刷卡、量詞', E'Asking prices and bargaining, shops and goods, colors and sizes, trying things on, paying by cash or card, measure words', E'這個多少錢？ | Zhège duōshao qián? | How much is this?\n太貴了。 | Tài guì le. | It is too expensive.\n我要買一件衣服。 | Wǒ yào mǎi yí jiàn yīfu. | I want to buy a piece of clothing.', E'錢 | qián | money\n塊 | kuài | dollar (spoken)\n元 | yuán | dollar (written)\n多少錢 | duōshao qián | how much\n貴 | guì | expensive\n打折 | dǎzhé | to give a discount\n一共 | yígòng | in total\n找錢 | zhǎoqián | to give change\n商店 | shāngdiàn | shop\n便利商店 | biànlì shāngdiàn | convenience store\n市場 | shìchǎng | market\n百貨公司 | bǎihuò gōngsī | department store\n夜市 | yèshì | night market\n衣服 | yīfu | clothes\n褲子 | kùzi | pants\n鞋子 | xiézi | shoes\n帽子 | màozi | hat\n書 | shū | book\n手機 | shǒujī | mobile phone\n包包 | bāobāo | bag\n東西 | dōngxi | thing\n筆 | bǐ | pen\n紅色 | hóngsè | red\n藍色 | lánsè | blue\n黑色 | hēisè | black\n白色 | báisè | white\n綠色 | lǜsè | green\n黃色 | huángsè | yellow\n新 | xīn | new\n舊 | jiù | old (not new)\n好看 | hǎokàn | good-looking\n合適 | héshì | suitable\n買 | mǎi | to buy\n賣 | mài | to sell\n看 | kàn | to look\n試 | shì | to try\n穿 | chuān | to wear\n付 | fù | to pay\n刷卡 | shuākǎ | to pay by card\n件 | jiàn | measure word for clothes\n雙 | shuāng | pair\n條 | tiáo | measure word for long items', E'A：請問這件衣服多少錢？ | Qǐngwèn zhè jiàn yīfu duōshao qián? | How much is this piece of clothing?\nB：八百塊。 | Bābǎi kuài. | 800 dollars.\nA：太貴了，可以便宜一點嗎？ | Tài guì le, kěyǐ piányi yìdiǎn ma? | Too expensive. Can it be a bit cheaper?\nB：好，七百塊。你要試穿嗎？ | Hǎo, qībǎi kuài. Nǐ yào shìchuān ma? | OK, 700 dollars. Do you want to try it on?\nA：好，這件有藍色嗎？ | Hǎo, zhè jiàn yǒu lánsè ma? | OK. Does this one come in blue?\nB：有，請等一下。 | Yǒu, qǐng děng yíxià. | Yes, please wait a moment.\nA：可以刷卡嗎？ | Kěyǐ shuākǎ ma? | Can I pay by card?\nB：可以。 | Kěyǐ. | Yes, you can.', E'購物與飲食', E'Shopping & Food'),
    (7, E'地點與問路', E'Places & Directions', 12, E'常見地點、方位詞、「在」與「有」、問路與指路、距離遠近', E'Common places, position words, 在 and 有, asking for and giving directions, near and far', E'郵局在銀行旁邊。 | Yóujú zài yínháng pángbiān. | The post office is next to the bank.\n廁所在哪裡？ | Cèsuǒ zài nǎlǐ? | Where is the restroom?\n一直走，到路口右轉。 | Yìzhí zǒu, dào lùkǒu yòu zhuǎn. | Go straight, then turn right at the intersection.', E'學校 | xuéxiào | school\n醫院 | yīyuàn | hospital\n銀行 | yínháng | bank\n郵局 | yóujú | post office\n車站 | chēzhàn | station\n公園 | gōngyuán | park\n廁所 | cèsuǒ | restroom\n圖書館 | túshūguǎn | library\n飯店 | fàndiàn | hotel\n機場 | jīchǎng | airport\n超市 | chāoshì | supermarket\n上 | shàng | up\n下 | xià | down\n前面 | qiánmiàn | front\n後面 | hòumiàn | back\n左邊 | zuǒbian | left side\n右邊 | yòubian | right side\n旁邊 | pángbiān | beside\n對面 | duìmiàn | opposite\n裡面 | lǐmiàn | inside\n外面 | wàimiàn | outside\n中間 | zhōngjiān | middle\n走 | zǒu | to walk\n轉 | zhuǎn | to turn\n到 | dào | to arrive\n找 | zhǎo | to look for\n問 | wèn | to ask\n知道 | zhīdào | to know\n哪裡 | nǎlǐ | where\n怎麼走 | zěnme zǒu | how to get there\n多遠 | duō yuǎn | how far\n路 | lù | road\n街 | jiē | street\n紅綠燈 | hónglǜdēng | traffic light\n路口 | lùkǒu | intersection\n一直 | yìzhí | straight on\n遠 | yuǎn | far\n近 | jìn | near\n離 | lí | away from\n公尺 | gōngchǐ | meter\n分鐘 | fēnzhōng | minute', E'A：請問，郵局在哪裡？ | Qǐngwèn, yóujú zài nǎlǐ? | Excuse me, where is the post office?\nB：在前面，銀行的旁邊。 | Zài qiánmiàn, yínháng de pángbiān. | Ahead, next to the bank.\nA：離這裡遠嗎？ | Lí zhèlǐ yuǎn ma? | Is it far from here?\nB：不遠，走路五分鐘。 | Bù yuǎn, zǒulù wǔ fēnzhōng. | Not far. It is five minutes on foot.\nA：我要怎麼走？ | Wǒ yào zěnme zǒu? | How do I get there?\nB：一直走，到紅綠燈右轉。 | Yìzhí zǒu, dào hónglǜdēng yòu zhuǎn. | Go straight, then turn right at the traffic light.\nA：謝謝你！ | Xièxie nǐ! | Thank you!\nB：不客氣。 | Bú kèqi. | You are welcome.', E'交通與出行', E'Getting Around'),
    (8, E'交通', E'Transportation', 9, E'交通工具、「坐／騎／開」、「從……到……」、搭車時間、買票與換車', E'Means of transport, 坐 / 騎 / 開, 從……到……, travel time, buying tickets and transferring', E'我坐公車去學校。 | Wǒ zuò gōngchē qù xuéxiào. | I take the bus to school.\n去機場怎麼走？ | Qù jīchǎng zěnme zǒu? | How do I get to the airport?\n要坐四十分鐘。 | Yào zuò sìshí fēnzhōng. | It takes forty minutes.', E'公車 | gōngchē | bus\n捷運 | jiéyùn | MRT\n火車 | huǒchē | train\n高鐵 | gāotiě | high-speed rail\n計程車 | jìchéngchē | taxi\n飛機 | fēijī | airplane\n腳踏車 | jiǎotàchē | bicycle\n機車 | jīchē | scooter\n船 | chuán | boat\n站 | zhàn | stop\n出口 | chūkǒu | exit\n入口 | rùkǒu | entrance\n坐 | zuò | to ride (as a passenger)\n騎 | qí | to ride (a bike)\n開 | kāi | to drive\n去 | qù | to go\n來 | lái | to come\n回 | huí | to return\n下車 | xià chē | to get off\n上車 | shàng chē | to get on\n換車 | huàn chē | to transfer\n票 | piào | ticket\n買票 | mǎi piào | to buy a ticket\n單程 | dānchéng | one way\n來回 | láihuí | round trip\n小時 | xiǎoshí | hour\n多久 | duōjiǔ | how long\n早 | zǎo | early\n晚 | wǎn | late\n快 | kuài | fast\n慢 | màn | slow\n從 | cóng | from\n司機 | sījī | driver', E'A：請問，去機場怎麼走？ | Qǐngwèn, qù jīchǎng zěnme zǒu? | Excuse me, how do I get to the airport?\nB：你可以坐捷運，在台北車站換車。 | Nǐ kěyǐ zuò jiéyùn, zài Táiběi chēzhàn huàn chē. | You can take the MRT and transfer at Taipei Main Station.\nA：要坐多久？ | Yào zuò duōjiǔ? | How long does it take?\nB：大概四十分鐘。 | Dàgài sìshí fēnzhōng. | About forty minutes.\nA：謝謝，我想買一張單程票。 | Xièxie, wǒ xiǎng mǎi yì zhāng dānchéng piào. | Thanks. I would like a one-way ticket.\nB：好的，一共八十元。 | Hǎo de, yígòng bāshí yuán. | OK, 80 dollars in total.', E'交通與出行', E'Getting Around'),
    (9, E'日常作息', E'Daily Routine', 10, E'一天的作息、頻率副詞、「先……然後……」、時間詞位置、「以後」', E'A daily routine, frequency adverbs, 先……然後……, where time words go, 以後', E'我早上七點起床。 | Wǒ zǎoshang qī diǎn qǐchuáng. | I get up at seven in the morning.\n我每天喝咖啡。 | Wǒ měitiān hē kāfēi. | I drink coffee every day.\n下班以後我去運動。 | Xiàbān yǐhòu wǒ qù yùndòng. | After work I go to exercise.', E'中午 | zhōngwǔ | noon\n每天 | měitiān | every day\n平常 | píngcháng | usually\n常常 | chángcháng | often\n有時候 | yǒu shíhou | sometimes\n從來不 | cónglái bù | never\n已經 | yǐjīng | already\n還沒 | hái méi | not yet\n起床 | qǐchuáng | to get up\n刷牙 | shuāyá | to brush teeth\n洗澡 | xǐzǎo | to take a shower\n吃早餐 | chī zǎocān | to eat breakfast\n上班 | shàngbān | to go to work\n下班 | xiàbān | to get off work\n上課 | shàngkè | to attend class\n下課 | xiàkè | to finish class\n回家 | huíjiā | to go home\n睡覺 | shuìjiào | to sleep\n休息 | xiūxi | to rest\n看書 | kànshū | to read\n看電視 | kàn diànshì | to watch TV\n運動 | yùndòng | to exercise\n做飯 | zuòfàn | to cook\n洗衣服 | xǐ yīfu | to do laundry\n玩 | wán | to play\n聽音樂 | tīng yīnyuè | to listen to music\n上網 | shàngwǎng | to go online\n然後 | ránhòu | then\n先 | xiān | first\n再 | zài | again or then\n一起 | yìqǐ | together\n每 | měi | every\n累 | lèi | tired\n以後 | yǐhòu | after', E'A：你每天幾點起床？ | Nǐ měitiān jǐ diǎn qǐchuáng? | What time do you get up every day?\nB：我平常六點半起床，然後吃早餐。 | Wǒ píngcháng liù diǎn bàn qǐchuáng, ránhòu chī zǎocān. | Usually 6:30, then I eat breakfast.\nA：你幾點上班？ | Nǐ jǐ diǎn shàngbān? | What time do you start work?\nB：八點半。下班以後我常常去運動。 | Bā diǎn bàn. Xiàbān yǐhòu wǒ chángcháng qù yùndòng. | 8:30. After work I often exercise.\nA：你幾點睡覺？ | Nǐ jǐ diǎn shuìjiào? | What time do you go to bed?\nB：我十一點睡覺。 | Wǒ shíyī diǎn shuìjiào. | I go to bed at eleven.', E'日常生活', E'Daily Life'),
    (10, E'天氣與衣著', E'Weather & Clothing', 10, E'天氣與四季、「很＋形容詞」、「會」表示預測、「有點」、依天氣選衣物與帶東西', E'Weather and seasons, 很 plus adjectives, 會 for predictions, 有點, choosing clothes and what to bring by the weather', E'今天很熱。 | Jīntiān hěn rè. | Today is very hot.\n明天會下雨。 | Míngtiān huì xià yǔ. | It will rain tomorrow.\n我要穿外套。 | Wǒ yào chuān wàitào. | I will wear a coat.', E'天氣 | tiānqì | weather\n晴天 | qíngtiān | sunny day\n陰天 | yīntiān | cloudy day\n下雨 | xià yǔ | to rain\n下雪 | xià xuě | to snow\n風 | fēng | wind\n太陽 | tàiyáng | sun\n雲 | yún | cloud\n溫度 | wēndù | temperature\n度 | dù | degree\n舒服 | shūfu | comfortable\n悶 | mèn | stuffy\n熱 | rè | hot\n冷 | lěng | cold\n涼快 | liángkuài | cool\n暖和 | nuǎnhuo | warm\n潮濕 | cháoshī | humid\n乾 | gān | dry\n春天 | chūntiān | spring\n夏天 | xiàtiān | summer\n秋天 | qiūtiān | autumn\n冬天 | dōngtiān | winter\n季節 | jìjié | season\n外套 | wàitào | coat\n襯衫 | chènshān | shirt\n裙子 | qúnzi | skirt\n高跟鞋 | gāogēnxié | high heels\n輕 | qīng | light\n厚 | hòu | thick\n雨傘 | yǔsǎn | umbrella\n帶 | dài | to bring\n眼鏡 | yǎnjìng | glasses\n太陽眼鏡 | tàiyáng yǎnjìng | sunglasses\n會 | huì | will\n可能 | kěnéng | maybe\n有點 | yǒudiǎn | a bit', E'A：明天天氣怎麼樣？ | Míngtiān tiānqì zěnmeyàng? | How will the weather be tomorrow?\nB：明天會下雨，而且很冷。 | Míngtiān huì xià yǔ, érqiě hěn lěng. | It will rain tomorrow, and it will be cold.\nA：那我要穿外套，還要帶雨傘。 | Nà wǒ yào chuān wàitào, hái yào dài yǔsǎn. | Then I will wear a coat and bring an umbrella.\nB：對，別忘了。 | Duì, bié wàng le. | Right, do not forget.\nA：我的帽子也要帶嗎？ | Wǒ de màozi yě yào dài ma? | Do I need to bring my hat too?\nB：不用，帶雨傘就可以了。 | Búyòng, dài yǔsǎn jiù kěyǐ le. | No need. An umbrella is enough.', E'日常生活', E'Daily Life'),
    (11, E'興趣與邀約', E'Hobbies & Invitations', 10, E'興趣與運動、邀請朋友、接受與婉拒、「會」表示能力、「好不好」', E'Hobbies and sports, inviting a friend, accepting and declining, 會 for ability, 好不好', E'我喜歡游泳。 | Wǒ xǐhuan yóuyǒng. | I like swimming.\n我們一起去看電影，好不好？ | Wǒmen yìqǐ qù kàn diànyǐng, hǎo bù hǎo? | Shall we go see a movie together?\n不好意思，我沒空。 | Bù hǎoyìsi, wǒ méi kòng. | Sorry, I am busy.', E'興趣 | xìngqù | hobby\n愛 | ài | to love\n音樂 | yīnyuè | music\n電影 | diànyǐng | movie\n旅行 | lǚxíng | travel\n照相 | zhàoxiàng | to take photos\n唱歌 | chànggē | to sing\n跳舞 | tiàowǔ | to dance\n畫畫 | huàhuà | to draw\n游泳 | yóuyǒng | to swim\n跑步 | pǎobù | to run\n打球 | dǎqiú | to play ball games\n籃球 | lánqiú | basketball\n足球 | zúqiú | soccer\n羽毛球 | yǔmáoqiú | badminton\n爬山 | páshān | to hike\n騎車 | qíchē | to ride a bike\n逛街 | guàngjiē | to go shopping\n看電影 | kàn diànyǐng | to watch a movie\n玩遊戲 | wán yóuxì | to play games\n打電話 | dǎ diànhuà | to make a call\n聚會 | jùhuì | get-together\n約會 | yuēhuì | date\n有空 | yǒu kòng | to be free\n沒空 | méi kòng | to be busy\n好啊 | hǎo a | sure\n好不好 | hǎo bù hǎo | is that okay?\n可以 | kěyǐ | can\n不好意思 | bù hǎoyìsi | sorry (to decline)\n下次 | xiàcì | next time\n當然 | dāngrán | of course\n為什麼 | wèishénme | why\n想 | xiǎng | to want to\n最 | zuì | most', E'A：這個週末你有空嗎？ | Zhège zhōumò nǐ yǒu kòng ma? | Are you free this weekend?\nB：有啊，你想做什麼？ | Yǒu a, nǐ xiǎng zuò shénme? | Yes. What do you want to do?\nA：我們一起去看電影，好不好？ | Wǒmen yìqǐ qù kàn diànyǐng, hǎo bù hǎo? | Shall we go see a movie together?\nB：好啊！幾點？ | Hǎo a! Jǐ diǎn? | Sure! What time?\nA：下午三點，在電影院門口見。 | Xiàwǔ sān diǎn, zài diànyǐngyuàn ménkǒu jiàn. | 3 p.m., meet at the cinema entrance.\nB：太好了，我們到時候見！ | Tài hǎo le, wǒmen dào shíhou jiàn! | Great, see you then!', E'社交與休閒', E'Social & Leisure'),
    (12, E'健康與生活服務', E'Health & Daily Services', 8, E'身體部位與症狀、掛號看病、「有點」與「了」、聽懂醫生建議、打電話預約、郵局與銀行', E'Body parts and symptoms, registering and seeing a doctor, 有點 and 了, understanding the doctor, booking by phone, the post office and bank', E'我頭痛。 | Wǒ tóutòng. | I have a headache.\n我有點發燒。 | Wǒ yǒudiǎn fāshāo. | I have a slight fever.\n我想預約明天下午。 | Wǒ xiǎng yùyuē míngtiān xiàwǔ. | I would like to book tomorrow afternoon.', E'頭 | tóu | head\n眼睛 | yǎnjing | eye\n耳朵 | ěrduo | ear\n鼻子 | bízi | nose\n嘴 | zuǐ | mouth\n手 | shǒu | hand\n腳 | jiǎo | foot\n肚子 | dùzi | stomach\n喉嚨 | hóulóng | throat\n身體 | shēntǐ | body\n不舒服 | bù shūfu | unwell\n痛 | tòng | pain\n頭痛 | tóutòng | headache\n發燒 | fāshāo | fever\n咳嗽 | késou | to cough\n感冒 | gǎnmào | cold (illness)\n拉肚子 | lā dùzi | to have diarrhea\n診所 | zhěnsuǒ | clinic\n掛號 | guàhào | to register\n藥 | yào | medicine\n吃藥 | chī yào | to take medicine\n藥局 | yàojú | pharmacy\n寄 | jì | to mail\n包裹 | bāoguǒ | parcel\n信 | xìn | letter\n了 | le | change or completion particle\n應該 | yīnggāi | should\n多 | duō | more\n喂 | wéi | hello (on the phone)\n預約 | yùyuē | to make an appointment', E'A：你哪裡不舒服？ | Nǐ nǎlǐ bù shūfu? | What is wrong?\nB：我頭痛，有點發燒，也咳嗽。 | Wǒ tóutòng, yǒudiǎn fāshāo, yě késou. | I have a headache, a slight fever and a cough.\nA：從什麼時候開始的？ | Cóng shénme shíhou kāishǐ de? | Since when?\nB：從昨天開始。 | Cóng zuótiān kāishǐ. | Since yesterday.\nA：你感冒了。多休息，一天吃三次藥。 | Nǐ gǎnmào le. Duō xiūxi, yì tiān chī sān cì yào. | You have a cold. Rest more and take the medicine three times a day.\nB：謝謝醫生。我想預約下次的時間。 | Xièxie yīshēng. Wǒ xiǎng yùyuē xiàcì de shíjiān. | Thank you, doctor. I would like to book the next visit.', E'健康與生活服務', E'Health & Services'),
    (13, E'工作場所與職務', E'Workplace & Jobs', 16, E'工廠、看護、營造與農漁業的職務名稱、機器與工具、班別與打卡、聽懂簡單的工作指令', E'Jobs in factories, caregiving, construction, farming and fishing, machines and tools, shifts and clocking in, understanding simple work instructions', E'我在工廠工作。 | Wǒ zài gōngchǎng gōngzuò. | I work in a factory.\n組長教我用機器。 | Zǔzhǎng jiāo wǒ yòng jīqì. | The team leader teaches me to use the machine.\n請幫我搬這個箱子。 | Qǐng bāng wǒ bān zhège xiāngzi. | Please help me carry this box.', E'工廠 | gōngchǎng | factory\n老闆 | lǎobǎn | boss\n經理 | jīnglǐ | manager\n組長 | zǔzhǎng | team leader\n員工 | yuángōng | employee\n外籍勞工 | wàijí láogōng | foreign worker\n看護 | kānhù | caregiver\n工人 | gōngrén | worker\n漁工 | yúgōng | fishing worker\n建築 | jiànzhù | construction\n農場 | nóngchǎng | farm\n倉庫 | cāngkù | warehouse\n辦公室 | bàngōngshì | office\n機器 | jīqì | machine\n工具 | gōngjù | tool\n材料 | cáiliào | material\n產品 | chǎnpǐn | product\n貨 | huò | goods\n箱子 | xiāngzi | box\n桌子 | zhuōzi | table\n椅子 | yǐzi | chair\n工作服 | gōngzuòfú | work uniform\n生產線 | shēngchǎnxiàn | production line\n班 | bān | shift\n早班 | zǎobān | day shift\n夜班 | yèbān | night shift\n打卡 | dǎkǎ | to clock in\n開會 | kāihuì | to have a meeting\n做 | zuò | to do\n搬 | bān | to carry\n放 | fàng | to put\n拿 | ná | to take\n用 | yòng | to use\n修 | xiū | to fix\n洗 | xǐ | to wash\n打掃 | dǎsǎo | to clean\n整理 | zhěnglǐ | to tidy up\n包裝 | bāozhuāng | to pack\n檢查 | jiǎnchá | to check\n幫忙 | bāngmáng | to help\n學 | xué | to learn\n教 | jiāo | to teach\n師傅 | shīfu | skilled worker\n翻譯 | fānyì | interpreter\n仲介 | zhòngjiè | labor broker\n輸送帶 | shūsòngdài | conveyor belt\n焊接 | hànjiē | welding\n油漆 | yóuqī | paint\n水泥 | shuǐní | cement\n漁船 | yúchuán | fishing boat\n種 | zhòng | to plant\n任務 | rènwù | task\n速度 | sùdù | speed\n品質 | pǐnzhì | quality\n數量 | shùliàng | quantity\n輪班 | lúnbān | rotating shifts\n貨車 | huòchē | truck', E'A：你在哪裡工作？ | Nǐ zài nǎlǐ gōngzuò? | Where do you work?\nB：我在工廠工作，我是工人。 | Wǒ zài gōngchǎng gōngzuò, wǒ shì gōngrén. | I work in a factory. I am a worker.\nA：你們幾點上班？ | Nǐmen jǐ diǎn shàngbān? | What time do you start work?\nB：我上早班，七點打卡。 | Wǒ shàng zǎobān, qī diǎn dǎkǎ. | I work the day shift and clock in at seven.\nA：組長教你用機器了嗎？ | Zǔzhǎng jiāo nǐ yòng jīqì le ma? | Has the team leader taught you to use the machine?\nB：教了，我會用了。 | Jiāo le, wǒ huì yòng le. | Yes, I can use it now.', E'職場工作', E'Workplace'),
    (14, E'工作指令與安全', E'Work Instructions & Safety', 17, E'安全帽與防護用品、危險與警告用語、受傷與急救、火災與逃生、「別」「一定要」的祈使句', E'Helmets and protective gear, danger and warning words, injuries and first aid, fire and escape, commands with 別 and 一定要', E'小心，地板很滑。 | Xiǎoxīn, dìbǎn hěn huá. | Be careful, the floor is slippery.\n工作的時候一定要戴安全帽。 | Gōngzuò de shíhou yídìng yào dài ānquánmào. | You must wear a helmet while working.\n機器壞了，請先關掉。 | Jīqì huài le, qǐng xiān guān diào. | The machine is broken, please turn it off first.', E'安全 | ānquán | safety\n危險 | wēixiǎn | dangerous\n小心 | xiǎoxīn | to be careful\n注意 | zhùyì | to pay attention\n停 | tíng | to stop\n安全帽 | ānquánmào | safety helmet\n安全鞋 | ānquánxié | safety shoes\n護目鏡 | hùmùjìng | goggles\n耳塞 | ěrsāi | earplugs\n手套 | shǒutào | gloves\n口罩 | kǒuzhào | face mask\n戴 | dài | to wear (on head or face)\n關 | guān | to turn off\n打開 | dǎkāi | to turn on\n開關 | kāiguān | switch\n電 | diàn | electricity\n火 | huǒ | fire\n火災 | huǒzāi | fire disaster\n滅火器 | mièhuǒqì | fire extinguisher\n逃生 | táoshēng | to escape\n緊急 | jǐnjí | urgent\n受傷 | shòushāng | to get injured\n流血 | liúxiě | to bleed\n急救 | jíjiù | first aid\n救護車 | jiùhùchē | ambulance\n地板 | dìbǎn | floor\n滑 | huá | slippery\n重 | zhòng | heavy\n禁止 | jìnzhǐ | forbidden\n抽菸 | chōuyān | to smoke\n喝酒 | hējiǔ | to drink alcohol\n一定 | yídìng | must\n別 | bié | do not\n聽 | tīng | to listen\n聽懂 | tīngdǒng | to understand by listening\n看到 | kàndào | to see\n告訴 | gàosu | to tell\n報告 | bàogào | to report\n說明書 | shuōmíngshū | instruction manual\n標誌 | biāozhì | sign\n乾淨 | gānjìng | clean\n髒 | zāng | dirty\n壞 | huài | broken\n掉 | diào | to fall off or away\n馬上 | mǎshàng | right away\n化學 | huàxué | chemical\n有毒 | yǒudú | poisonous\n噪音 | zàoyīn | noise\n通風 | tōngfēng | ventilation\n警告 | jǐnggào | warning\n推 | tuī | to push\n拉 | lā | to pull\n爬 | pá | to climb\n梯子 | tīzi | ladder\n繩子 | shéngzi | rope\n安全帶 | ānquándài | safety belt\n灼傷 | zhuóshāng | burn injury\n骨折 | gǔzhé | fracture\n包紮 | bāozā | to bandage\n止血 | zhǐxiě | to stop bleeding', E'A：小心！那裡很危險！ | Xiǎoxīn! Nàlǐ hěn wēixiǎn! | Careful! It is very dangerous there!\nB：對不起，我沒看到。 | Duìbuqǐ, wǒ méi kàndào. | Sorry, I did not see it.\nA：你的安全帽呢？ | Nǐ de ānquánmào ne? | Where is your helmet?\nB：在桌子上，我現在去拿。 | Zài zhuōzi shàng, wǒ xiànzài qù ná. | It is on the table. I will go get it now.\nA：機器壞了，請先關掉。 | Jīqì huài le, qǐng xiān guān diào. | The machine is broken, please turn it off first.\nB：好，我馬上關。 | Hǎo, wǒ mǎshàng guān. | OK, I will turn it off right away.', E'職場工作', E'Workplace'),
    (15, E'薪水、請假與加班', E'Pay, Leave & Overtime', 15, E'薪水與加班費、薪資單、匯款與存款、請假與休假、合約與工時、準時與遲到', E'Salary and overtime pay, pay slips, remitting and saving money, asking for leave and days off, contracts and working hours, being on time and late', E'我每個月十號發薪水。 | Wǒ měi ge yuè shí hào fā xīnshuǐ. | I get paid on the 10th of every month.\n我想請兩天假。 | Wǒ xiǎng qǐng liǎng tiān jià. | I would like to take two days of leave.\n今天要加班兩個小時。 | Jīntiān yào jiābān liǎng ge xiǎoshí. | Today I have to work two hours of overtime.', E'薪水 | xīnshuǐ | salary\n發薪日 | fāxīnrì | payday\n月薪 | yuèxīn | monthly pay\n時薪 | shíxīn | hourly pay\n加班 | jiābān | to work overtime\n加班費 | jiābānfèi | overtime pay\n扣 | kòu | to deduct\n薪資單 | xīnzīdān | pay slip\n匯款 | huìkuǎn | to remit money\n寄錢 | jì qián | to send money\n匯率 | huìlǜ | exchange rate\n存 | cún | to deposit\n存款 | cúnkuǎn | savings\n提款機 | tíkuǎnjī | ATM\n帳戶 | zhànghù | bank account\n存摺 | cúnzhé | bankbook\n現金 | xiànjīn | cash\n請假 | qǐngjià | to ask for leave\n病假 | bìngjià | sick leave\n休假 | xiūjià | vacation\n放假 | fàngjià | to have a day off\n國定假日 | guódìng jiàrì | national holiday\n春節 | Chūnjié | Lunar New Year\n合約 | héyuē | contract\n簽 | qiān | to sign\n簽名 | qiānmíng | signature\n日期 | rìqī | date\n工時 | gōngshí | working hours\n午休 | wǔxiū | lunch break\n遲到 | chídào | to be late\n早退 | zǎotuì | to leave early\n準時 | zhǔnshí | on time\n月底 | yuèdǐ | end of the month\n月初 | yuèchū | start of the month\n少 | shǎo | few\n夠 | gòu | enough\n需要 | xūyào | to need\n問題 | wèntí | problem\n算 | suàn | to calculate\n錯 | cuò | wrong\n菲律賓 | Fēilǜbīn | the Philippines\n家人 | jiārén | family members\n比索 | bǐsuǒ | peso\n台幣 | táibì | Taiwan dollar\n生病 | shēngbìng | to get sick\n稅 | shuì | tax\n保險 | bǎoxiǎn | insurance\n獎金 | jiǎngjīn | bonus\n轉帳 | zhuǎnzhàng | to transfer money\n手續費 | shǒuxùfèi | service fee\n換錢 | huànqián | to exchange money\n存錢 | cúnqián | to save money\n借錢 | jièqián | to borrow money\n花錢 | huāqián | to spend money\n省錢 | shěngqián | to economize', E'A：老闆，我想請假。 | Lǎobǎn, wǒ xiǎng qǐngjià. | Boss, I would like to ask for leave.\nB：你要請幾天？ | Nǐ yào qǐng jǐ tiān? | How many days do you want?\nA：請三天，我家人生病了。 | Qǐng sān tiān, wǒ jiārén shēngbìng le. | Three days. My family member is sick.\nB：好，請你簽名。 | Hǎo, qǐng nǐ qiānmíng. | OK, please sign your name.\nA：謝謝老闆。薪水什麼時候發？ | Xièxie lǎobǎn. Xīnshuǐ shénme shíhou fā? | Thank you, boss. When is the salary paid?\nB：每個月十號。 | Měi ge yuè shí hào. | On the 10th of every month.', E'職場工作', E'Workplace'),
    (16, E'住宿與生活設施', E'Housing & Living Facilities', 17, E'宿舍與房間、家具與家電、水電瓦斯與費用、垃圾分類與宿舍規定、與室友相處', E'Dormitory and rooms, furniture and appliances, water, electricity, gas and bills, trash and dorm rules, living with roommates', E'我住在公司的宿舍。 | Wǒ zhù zài gōngsī de sùshè. | I live in the company dormitory.\n房間裡有一張床。 | Fángjiān lǐ yǒu yì zhāng chuáng. | There is a bed in the room.\n晚上十點以後請安靜。 | Wǎnshang shí diǎn yǐhòu qǐng ānjìng. | Please be quiet after ten at night.', E'宿舍 | sùshè | dormitory\n房間 | fángjiān | room\n房子 | fángzi | house\n房租 | fángzū | rent\n室友 | shìyǒu | roommate\n床 | chuáng | bed\n被子 | bèizi | blanket\n枕頭 | zhěntou | pillow\n衣櫃 | yīguì | wardrobe\n窗戶 | chuānghu | window\n門 | mén | door\n鑰匙 | yàoshi | key\n燈 | dēng | light\n冷氣 | lěngqì | air conditioner\n電風扇 | diànfēngshàn | electric fan\n電視 | diànshì | television\n冰箱 | bīngxiāng | refrigerator\n洗衣機 | xǐyījī | washing machine\n熱水 | rèshuǐ | hot water\n熱水器 | rèshuǐqì | water heater\n瓦斯 | wǎsī | gas\n插座 | chāzuò | power socket\n網路 | wǎnglù | internet\n無線網路 | wúxiàn wǎnglù | Wi-Fi\n廚房 | chúfáng | kitchen\n浴室 | yùshì | bathroom\n馬桶 | mǎtǒng | toilet\n肥皂 | féizào | soap\n牙刷 | yáshuā | toothbrush\n毛巾 | máojīn | towel\n衛生紙 | wèishēngzhǐ | toilet paper\n垃圾 | lājī | trash\n垃圾車 | lājīchē | garbage truck\n倒垃圾 | dào lājī | to take out the trash\n安靜 | ānjìng | quiet\n吵 | chǎo | noisy\n樓上 | lóushàng | upstairs\n樓下 | lóuxià | downstairs\n電費 | diànfèi | electricity bill\n水費 | shuǐfèi | water bill\n繳費 | jiǎofèi | to pay a bill\n搬家 | bānjiā | to move house\n地址 | dìzhǐ | address\n規定 | guīdìng | rule\n關燈 | guāndēng | to turn off the light\n借 | jiè | to borrow\n還 | huán | to return something\n陽台 | yángtái | balcony\n樓梯 | lóutī | stairs\n電梯 | diàntī | elevator\n洗髮精 | xǐfàjīng | shampoo\n牙膏 | yágāo | toothpaste\n拖鞋 | tuōxié | slippers\n掃把 | sàobǎ | broom\n拖把 | tuōbǎ | mop\n鍋子 | guōzi | pot\n碗 | wǎn | bowl\n盤子 | pánzi | plate\n湯匙 | tāngchí | spoon', E'A：這是我們的房間。 | Zhè shì wǒmen de fángjiān. | This is our room.\nB：房間很大，有冷氣嗎？ | Fángjiān hěn dà, yǒu lěngqì ma? | The room is big. Is there an air conditioner?\nA：有，也有冰箱和洗衣機。 | Yǒu, yě yǒu bīngxiāng hé xǐyījī. | Yes, and there is also a refrigerator and a washing machine.\nB：熱水在哪裡？ | Rèshuǐ zài nǎlǐ? | Where is the hot water?\nA：浴室裡有熱水器。 | Yùshì lǐ yǒu rèshuǐqì. | There is a water heater in the bathroom.\nB：房租一個月多少錢？ | Fángzū yí ge yuè duōshao qián? | How much is the rent per month?\nA：公司付房租，你付電費。 | Gōngsī fù fángzū, nǐ fù diànfèi. | The company pays the rent. You pay the electricity bill.', E'住宿與生活', E'Housing & Living'),
    (17, E'照顧長輩與看護', E'Caring for the Elderly', 16, E'照顧老人與病人的日常、餵飯洗澡與換尿布、量血壓體溫、散步與復健、與家屬溝通', E'Daily care of elderly people and patients, feeding, bathing and changing diapers, measuring blood pressure and temperature, walks and rehabilitation, talking with family members', E'我照顧阿公。 | Wǒ zhàogù āgōng. | I take care of grandpa.\n請慢慢走，我扶你。 | Qǐng mànmàn zǒu, wǒ fú nǐ. | Please walk slowly, I will support you.\n阿嬤要吃藥了。 | Āmā yào chī yào le. | Grandma needs to take her medicine.', E'照顧 | zhàogù | to take care of\n老人 | lǎorén | elderly person\n病人 | bìngrén | patient\n阿公 | āgōng | grandpa\n阿嬤 | āmā | grandma\n輪椅 | lúnyǐ | wheelchair\n扶 | fú | to support\n抱 | bào | to hold\n躺 | tǎng | to lie down\n起來 | qǐlái | to get up\n擦 | cā | to wipe\n換 | huàn | to change\n尿布 | niàobù | diaper\n餵 | wèi | to feed\n煮 | zhǔ | to cook\n軟 | ruǎn | soft\n粥 | zhōu | porridge\n湯 | tāng | soup\n血壓 | xuèyā | blood pressure\n量 | liáng | to measure\n體溫 | tǐwēn | body temperature\n復健 | fùjiàn | rehabilitation\n散步 | sànbù | to take a walk\n曬太陽 | shài tàiyáng | to sunbathe\n睡不著 | shuì bù zháo | cannot sleep\n半夜 | bànyè | midnight\n按 | àn | to press\n呼叫鈴 | hūjiàolíng | call bell\n跌倒 | diēdǎo | to fall down\n扶手 | fúshǒu | handrail\n耐心 | nàixīn | patience\n慢慢 | mànmàn | slowly\n輕輕 | qīngqīng | gently\n放心 | fàngxīn | to be reassured\n家屬 | jiāshǔ | family of a patient\n兒子 | érzi | son\n女兒 | nǚ''ér | daughter\n孫子 | sūnzi | grandson\n聊天 | liáotiān | to chat\n陪 | péi | to keep company\n完 | wán | to finish\n扶起來 | fú qǐlái | to help someone up\n擔心 | dānxīn | to worry\n痛苦 | tòngkǔ | suffering\n清醒 | qīngxǐng | awake\n餓 | è | hungry\n渴 | kě | thirsty\n呼吸 | hūxī | to breathe\n心跳 | xīntiào | heartbeat\n傷口 | shāngkǒu | wound\n藥膏 | yàogāo | ointment\n打針 | dǎzhēn | to get an injection\n血糖 | xuètáng | blood sugar\n高血壓 | gāoxuèyā | high blood pressure\n翻身 | fānshēn | to turn over\n按摩 | ànmó | massage', E'A：阿公，起來吃飯了。 | Āgōng, qǐlái chīfàn le. | Grandpa, get up, it is time to eat.\nB：我不想吃。 | Wǒ bù xiǎng chī. | I do not want to eat.\nA：我煮了軟的粥，很好吃。 | Wǒ zhǔ le ruǎn de zhōu, hěn hǎochī. | I cooked soft porridge. It is delicious.\nB：好，我吃一點。 | Hǎo, wǒ chī yìdiǎn. | OK, I will eat a little.\nA：吃完飯我們去散步，好不好？ | Chī wán fàn wǒmen qù sànbù, hǎo bù hǎo? | After eating, shall we go for a walk?\nB：好啊，你慢慢扶我。 | Hǎo a, nǐ mànmàn fú wǒ. | Sure, support me slowly.', E'照顧與看護', E'Caregiving'),
    (18, E'手機、網路與聯絡家人', E'Phone, Internet & Staying in Touch', 15, E'手機與充電、網路與視訊、國際電話與儲值、寄包裹給家人、聽不懂時請對方再說一次', E'Phones and charging, internet and video calls, international calls and top-ups, mailing parcels to family, asking someone to repeat when you do not understand', E'我的手機沒電了。 | Wǒ de shǒujī méi diàn le. | My phone is out of battery.\n我想跟家人視訊。 | Wǒ xiǎng gēn jiārén shìxùn. | I want to video call my family.\n請給我你的帳號。 | Qǐng gěi wǒ nǐ de zhànghào. | Please give me your account name.', E'簡訊 | jiǎnxùn | text message\n訊息 | xùnxī | message\n充電 | chōngdiàn | to charge\n充電器 | chōngdiànqì | charger\n電池 | diànchí | battery\n螢幕 | yíngmù | screen\n密碼 | mìmǎ | password\n帳號 | zhànghào | account name\n下載 | xiàzài | to download\n應用程式 | yìngyòng chéngshì | app\n視訊 | shìxùn | video call\n照片 | zhàopiàn | photo\n傳 | chuán | to send\n收到 | shōudào | to receive\n接 | jiē | to answer a call\n掛斷 | guàduàn | to hang up\n忘記 | wàngjì | to forget\n沒電 | méi diàn | out of battery\n訊號 | xùnhào | signal\n流量 | liúliàng | mobile data\n預付卡 | yùfùkǎ | prepaid card\n儲值 | chǔzhí | to top up\n通話 | tōnghuà | phone call\n國際電話 | guójì diànhuà | international call\n聯絡 | liánluò | to contact\n想念 | xiǎngniàn | to miss someone\n想家 | xiǎng jiā | to be homesick\n家鄉 | jiāxiāng | hometown\n禮物 | lǐwù | gift\n快遞 | kuàidì | express delivery\n郵費 | yóufèi | postage\n收件人 | shōujiànrén | recipient\n英文 | Yīngwén | English\n中文 | Zhōngwén | Chinese\n說 | shuō | to speak\n聽不懂 | tīng bu dǒng | cannot understand by listening\n懂 | dǒng | to understand\n大聲 | dàshēng | loudly\n小聲 | xiǎoshēng | softly\n跟 | gēn | with\n比較 | bǐjiào | rather\n重複 | chóngfù | to repeat\n發音 | fāyīn | pronunciation\n寫 | xiě | to write\n念 | niàn | to read aloud\n字 | zì | character\n拍照 | pāizhào | to take a picture\n影片 | yǐngpiàn | video\n聲音 | shēngyīn | voice\n清楚 | qīngchu | clear\n斷線 | duànxiàn | disconnected\n設定 | shèdìng | settings\n登入 | dēngrù | to log in', E'A：我想打電話給家人。 | Wǒ xiǎng dǎ diànhuà gěi jiārén. | I want to call my family.\nB：你可以用我的手機。 | Nǐ kěyǐ yòng wǒ de shǒujī. | You can use my phone.\nA：國際電話貴不貴？ | Guójì diànhuà guì bú guì? | Are international calls expensive?\nB：很貴，用網路視訊比較便宜。 | Hěn guì, yòng wǎnglù shìxùn bǐjiào piányi. | Yes. Video calls over the internet are cheaper.\nA：你有無線網路嗎？ | Nǐ yǒu wúxiàn wǎnglù ma? | Do you have Wi-Fi?\nB：有，密碼在桌子上。 | Yǒu, mìmǎ zài zhuōzi shàng. | Yes, the password is on the table.', E'通訊與求助', E'Communication & Help'),
    (19, E'求助、緊急與證件', E'Asking for Help, Emergencies & Documents', 13, E'報警與叫救護車、遺失護照與居留證、填寫表格、勞工諮詢專線、說出自己的問題與地點', E'Calling the police and an ambulance, losing a passport or residence permit, filling in forms, the labor hotline, explaining your problem and location', E'救命！請打一一九。 | Jiùmìng! Qǐng dǎ yāo yāo jiǔ. | Help! Please call 119.\n我的護照不見了。 | Wǒ de hùzhào bú jiàn le. | My passport is missing.\n請你幫我填這張表格。 | Qǐng nǐ bāng wǒ tián zhè zhāng biǎogé. | Please help me fill in this form.', E'救命 | jiùmìng | help\n求助 | qiúzhù | to ask for help\n警察 | jǐngchá | police officer\n警察局 | jǐngchájú | police station\n派出所 | pàichūsuǒ | local police station\n急診 | jízhěn | emergency room\n發生 | fāshēng | to happen\n事情 | shìqing | matter\n出事 | chūshì | to have an accident\n車禍 | chēhuò | car accident\n小偷 | xiǎotōu | thief\n偷 | tōu | to steal\n丟 | diū | to lose\n不見了 | bú jiàn le | gone missing\n護照 | hùzhào | passport\n居留證 | jūliúzhèng | residence permit\n簽證 | qiānzhèng | visa\n健保卡 | jiànbǎokǎ | health insurance card\n證件 | zhèngjiàn | ID document\n申請 | shēnqǐng | to apply\n表格 | biǎogé | form\n填 | tián | to fill in\n國籍 | guójí | nationality\n勞工局 | láogōngjú | labor bureau\n專線 | zhuānxiàn | hotline\n諮詢 | zīxún | consultation\n幫助 | bāngzhù | assistance\n趕快 | gǎnkuài | hurry up\n怕 | pà | to be afraid\n冷靜 | lěngjìng | calm\n等 | děng | to wait\n地點 | dìdiǎn | location\n權利 | quánlì | rights\n保護 | bǎohù | to protect\n合法 | héfǎ | legal\n法律 | fǎlǜ | law\n罰款 | fákuǎn | fine\n打架 | dǎjià | to fight\n吵架 | chǎojià | to quarrel\n欺負 | qīfu | to bully\n害怕 | hàipà | scared\n危急 | wēijí | critical\n說清楚 | shuō qīngchu | to explain clearly\n證明 | zhèngmíng | proof\n影本 | yǐngběn | photocopy', E'A：請問，派出所在哪裡？ | Qǐngwèn, pàichūsuǒ zài nǎlǐ? | Excuse me, where is the police station?\nB：在前面，走路五分鐘。 | Zài qiánmiàn, zǒulù wǔ fēnzhōng. | Ahead, five minutes on foot.\nA：我的護照丟了。 | Wǒ de hùzhào diū le. | I lost my passport.\nB：別擔心，請你填這張表格。 | Bié dānxīn, qǐng nǐ tián zhè zhāng biǎogé. | Do not worry. Please fill in this form.\nA：好，我需要翻譯嗎？ | Hǎo, wǒ xūyào fānyì ma? | OK, do I need an interpreter?\nB：不用，我會說一點英文。 | Búyòng, wǒ huì shuō yìdiǎn Yīngwén. | No need. I can speak a little English.', E'通訊與求助', E'Communication & Help'),
    (20, E'總複習與模擬測驗', E'Review & Mock Test', 10, E'前 12 個單元複習、聽力與閱讀模擬測驗（仿 TOCFL Level 1）、口說任務、錯題分析與成績回饋', E'Review of the first 12 units, listening and reading mock test (TOCFL Level 1 style), speaking tasks, mistake analysis and feedback', E'請問，廁所在哪裡？ | Qǐngwèn, cèsuǒ zài nǎlǐ? | Excuse me, where is the restroom?\n我想買一杯茶。 | Wǒ xiǎng mǎi yì bēi chá. | I would like to buy a cup of tea.\n我們一起去吃飯，好不好？ | Wǒmen yìqǐ qù chīfàn, hǎo bù hǎo? | Shall we go to eat together?', E'請問 | qǐngwèn | excuse me\n對不起 | duìbuqǐ | sorry\n沒關係 | méi guānxi | it is okay\n可以 | kěyǐ | can\n不可以 | bù kěyǐ | not allowed\n我要 | wǒ yào | I want\n我想 | wǒ xiǎng | I would like to\n我不知道 | wǒ bù zhīdào | I do not know\n請等一下 | qǐng děng yíxià | please wait a moment\n請再說一次 | qǐng zài shuō yí cì | please say it again\n慢一點 | màn yìdiǎn | slower\n謝謝 | xièxie | thank you\n不客氣 | bú kèqi | you are welcome\n再見 | zàijiàn | goodbye\n多少錢 | duōshao qián | how much\n怎麼走 | zěnme zǒu | how to get there\n幾點 | jǐ diǎn | what time\n在哪裡 | zài nǎlǐ | where is\n有沒有 | yǒu méiyǒu | is there\n好不好 | hǎo bù hǎo | is that okay?\n我不舒服 | wǒ bù shūfu | I do not feel well', E'A：請問，我可以今天下午請假嗎？ | Qǐngwèn, wǒ kěyǐ jīntiān xiàwǔ qǐngjià ma? | Excuse me, may I take leave this afternoon?\nB：為什麼？ | Wèishénme? | Why?\nA：我不舒服，要去醫院。 | Wǒ bù shūfu, yào qù yīyuàn. | I do not feel well and need to go to the hospital.\nB：好，請你小心。 | Hǎo, qǐng nǐ xiǎoxīn. | OK, please be careful.\nA：謝謝，我明天會回來上班。 | Xièxie, wǒ míngtiān huì huílái shàngbān. | Thank you. I will be back at work tomorrow.\nB：好，再見。 | Hǎo, zàijiàn. | OK, goodbye.', E'複習', E'Review')
  ) AS v(position, name, name_en, hours, topics, topics_en, examples, vocabulary, dialogue, category, category_en)
  ON CONFLICT (course_id, name) DO NOTHING
  RETURNING id
)
SELECT count(*) AS added FROM inserted \gset

COMMIT;
\echo '完成：新增單元數（0 代表之前已經新增過）：' :added
